/* art.js - generated artwork for the timeline, ads and catalog. Product drawings (40+ kinds), game scenes (30+), packaging
   (PC box, cartridge, disc case, arcade cabinet, floppy), movie posters, front pages, badges and seeded sprites.
   Everything is drawn from code and seeded by the title, so each entry gets its own picture and it never changes.
   Loaded after ads.js and icons.js. Uses srect, rng, hstr, esc, AD_SKY (app.js / ads.js), px glyphs (icons.js), GX and TLX when present. */
function ci(x,y,r,f,s,sw){return'<circle cx="'+x+'" cy="'+y+'" r="'+r+'" fill="'+f+'"'+(s?' stroke="'+s+'" stroke-width="'+(sw||2)+'"':"")+'/>'}
function po(p,f,s,sw){return'<polygon points="'+p+'" fill="'+f+'"'+(s?' stroke="'+s+'" stroke-width="'+(sw||2)+'"':"")+'/>'}
function ln(x1,y1,x2,y2,s,w){return'<line x1="'+x1+'" y1="'+y1+'" x2="'+x2+'" y2="'+y2+'" stroke="'+s+'" stroke-width="'+(w||2)+'"/>'}
function tx(x,y,t,sz,f,a,extra){return'<text x="'+x+'" y="'+y+'" font-family="monospace" font-weight="bold" font-size="'+sz+'" fill="'+f+'"'+(a?' text-anchor="'+a+'"':"")+(extra||"")+'>'+esc(t)+'</text>'}
function pth(d,f,s,sw){return'<path d="'+d+'" fill="'+(f||"none")+'"'+(s?' stroke="'+s+'" stroke-width="'+(sw||2)+'"':"")+'/>'}
function pxIn(name,x,y,s){var g=PXG[name]||PXG.chip,o='<g transform="translate('+x+' '+y+') scale('+(s/12)+')" shape-rendering="crispEdges">',r,c,i,run;
 for(r=0;r<12;r++){var row=(g[r]||"").padEnd(12,".");i=0;while(i<12){c=row[i];if(c==="."||!PXC[c]){i++;continue}run=1;while(i+run<12&&row[i+run]===c)run++;o+='<rect x="'+i+'" y="'+r+'" width="'+run+'" height="1" fill="'+PXC[c]+'"/>';i+=run}}
 return o+'</g>'}
