 for(var i=0;i<rules.length;i++)if(rules[i][0].test(hay)){var nm=rules[i][1];return{name:nm,idx:legacy[nm]}}
 if(WAR.test(hay))return{name:"war",idx:5};if(NOIR.test(hay))return{name:"noir",idx:3};
